//! Annotated Rust descriptor methods for the portable system API metadata.
//!
//! The language runtime implements these operations across the semantic,
//! evaluator, and runtime crates. This crate owns the callable descriptor
//! bindings; their attributes are collected at build time into the normative
//! signature catalogue.
//!
//! The collector uses `syn` over explicit source methods. Methods generated by Rust
//! macros are not visible to it and must be written explicitly or handled by a future
//! macro-expanding collector.

use std::{collections::BTreeSet, sync::LazyLock};

use super::{
    SystemEffect, SystemFunctionDescriptor, system_function_descriptor,
};
use orna_sys_macros::ornasys;

const GENERATED_SYSTEM_API: &str = include_str!(concat!(env!("OUT_DIR"), "/api_sys.json"));
const GENERATED_SYSTEM_SCHEMA: &str =
    include_str!(concat!(env!("OUT_DIR"), "/system_api_schema.json"));
const GENERATED_BINDING_STUBS: &str =
    include_str!(concat!(env!("OUT_DIR"), "/system_bindings.orna"));
const GENERATED_BINDING_MODULES: &str =
    include_str!(concat!(env!("OUT_DIR"), "/system_binding_modules.json"));

static EMBEDDED_SYS_SCHEMA_CHECK: LazyLock<()> = LazyLock::new(|| {
    let api: serde_json::Value =
        serde_json::from_str(GENERATED_SYSTEM_API).expect("build-validated generated sys API JSON");
    let schema: serde_json::Value = serde_json::from_str(GENERATED_SYSTEM_SCHEMA)
        .expect("build-validated generated sys JSON Schema");
    assert_eq!(
        schema["$schema"].as_str(),
        Some("https://json-schema.org/draft/2020-12/schema")
    );
    assert_eq!(schema["type"].as_str(), Some("object"));
    assert_eq!(schema["additionalProperties"], false);
    let api_fields = api
        .as_object()
        .expect("generated sys API root is an object")
        .keys()
        .cloned()
        .collect::<BTreeSet<_>>();
    let schema_fields = schema["properties"]
        .as_object()
        .expect("embedded sys schema properties are an object")
        .keys()
        .cloned()
        .collect::<BTreeSet<_>>();
    let required_fields = schema["required"]
        .as_array()
        .expect("embedded sys schema required fields are an array")
        .iter()
        .map(|field| {
            field
                .as_str()
                .expect("embedded sys schema field name is a string")
                .to_owned()
        })
        .collect::<BTreeSet<_>>();
    assert_eq!(api_fields, schema_fields);
    assert_eq!(api_fields, required_fields);
});

/// Runtime descriptors are parsed from the same canonical artifact emitted
/// from method attributes; build.rs does not emit a second Rust descriptor table.
pub static SYSTEM_FUNCTION_DESCRIPTORS: LazyLock<Vec<SystemFunctionDescriptor>> =
    LazyLock::new(|| {
        #[derive(serde::Deserialize)]
        struct Api<'a> {
            #[serde(borrow)]
            functions: Vec<Function<'a>>,
        }

        #[derive(serde::Deserialize)]
        struct Function<'a> {
            #[serde(borrow)]
            name: &'a str,
            #[serde(borrow)]
            effect: &'a str,
            #[serde(borrow)]
            signature: &'a str,
            #[serde(borrow)]
            purpose: &'a str,
            #[serde(borrow)]
            since: Option<&'a str>,
            #[serde(borrow)]
            documentation: Option<&'a str>,
            #[serde(borrow)]
            contract: Option<&'a str>,
            #[serde(borrow)]
            preconditions: Option<&'a str>,
            #[serde(borrow)]
            ownership: Option<&'a str>,
            #[serde(borrow)]
            snapshot_rule: Option<&'a str>,
        }

        let api: Api<'static> = serde_json::from_str(GENERATED_SYSTEM_API)
            .expect("build-validated generated system API JSON");
        api.functions
            .into_iter()
            .map(|function| {
                let effect = match function.effect {
                    "read" => SystemEffect::Read,
                    "invoke" => SystemEffect::Invoke,
                    "admin" => SystemEffect::Admin,
                    _ => unreachable!("build validation rejects unknown system effects"),
                };
                SystemFunctionDescriptor {
                    name: function.name,
                    effect,
                    signature: function.signature,
                    purpose: function.purpose,
                    since: function.since,
                    documentation: function.documentation,
                    contract: function.contract,
                    preconditions: function.preconditions,
                    ownership: function.ownership,
                    snapshot_rule: function.snapshot_rule,
                }
            })
            .collect()
    });

/// Returns the deterministic build-time projection of the annotated system API methods.
pub fn system_api_json() -> String {
    LazyLock::force(&EMBEDDED_SYS_SCHEMA_CHECK);
    GENERATED_SYSTEM_API.to_owned()
}

/// The JSON Schema generated beside the API artifact and embedded with the
/// baked sys registry. Production consumers use the compiled schema directly;
/// the dev-only exporter can emit the API document without a checked-in file.
pub fn system_api_schema_json() -> &'static str {
    LazyLock::force(&EMBEDDED_SYS_SCHEMA_CHECK);
    GENERATED_SYSTEM_SCHEMA
}

/// Deterministic Orna declaration bundle emitted from the typed native sys
/// registry. The corresponding module files are written beneath Cargo's
/// `OUT_DIR/system_bindings/` tree. These stubs are a type and dispatch
/// artifact, not executable implementations.
pub fn system_binding_stubs() -> &'static str {
    GENERATED_BINDING_STUBS
}

/// Canonical JSON map of each generated Orna sys module path to its source.
/// The dev-only exporter uses this manifest to reproduce the complete binding
/// module tree from the same compile-time generated bytes.
pub fn system_binding_modules_json() -> &'static str {
    GENERATED_BINDING_MODULES
}

/// Descriptor accessors for the portable system methods collected by `build.rs`.
///
/// These return signature metadata only; execution remains owned by semantic/runtime APIs.
pub struct SystemApiFunctionBindings;

